const {fitData} = DataScience;
const linear = NeuralNet.ACTIVATIONS.linear;
const nn = NeuralNet.builder().input(2).layer(25).layer(25).layer(1,
NeuralNet.ACTIVATIONS.sigmoid).build();
const samples = await IO.loadMNIST();
const sample = samples[31]
//MNIST is 28x28 = 784 1-array we want to map it into a [0,1]^2
const trainXs = Array.from(sample).map((_, i) => [(i % 28) / 27, 1.0 - Math.floor(i / 28) / 27])
const testXs = NArray.range(0,28).map(x => x / 27).prod(NArray.range(0,28).map(x => x / 27)).toArray().map(z => z.toArray());

const {theta} = fitData(trainXs, trainXs.map((_, i) => sample[i]), nn.model, {  epochs: 2500,  batch: 256,  learningRate: 0.01,  finiteDiff: false, optimizer: "adamw"});
console.log(theta);
nn.setWeights(theta);

let {scene} = IO.plotPointCloud(trainXs.map(([x,y], i) => [x, y, sample[i]]), {color:[1,0,0]});
IO.plotPointCloud(testXs.map(([x,y]) => [x, y, nn.eval([x, y])]), {scene, color:[0,0,1]})

IO.paintMNIST([sample, Float32Array.from(testXs.map(([x, y]) => nn.eval([y, 1 - x])))]);
